// Extract and validate callback data
const input = $input.first().json;
const body = input.body || {};

const data = body.data || {};
const metadata = data.metadata || {};

// Required fields
if (!data.customer_email) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Missing customer_email in data',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Determine plan and credits
const plan = metadata.plan || 'basic';
const creditsMap = {
  'free': 100,
  'basic': 1000,
  'premium': 5000,
  'unlimited': 999999
};
const rateLimitMap = {
  'free': { per_minute: 10, per_day: 100 },
  'basic': { per_minute: 30, per_day: 1000 },
  'premium': { per_minute: 60, per_day: 5000 },
  'unlimited': { per_minute: 120, per_day: 999999 }
};
const credits = creditsMap[plan] || 1000;
const rateLimit = rateLimitMap[plan] || rateLimitMap.basic;

// Generate API key
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
let apiKey = 'mcp_';
for (let i = 0; i < 56; i++) {
  apiKey += chars.charAt(Math.floor(Math.random() * chars.length));
}

return [{
  json: {
    valid: true,
    email: data.customer_email,
    name: metadata.name || null,
    company: metadata.company || null,
    stripe_customer_id: data.customer_id,
    stripe_subscription_id: data.subscription_id,
    plan: plan,
    credits_to_add: credits,
    rate_limit_per_minute: rateLimit.per_minute,
    rate_limit_per_day: rateLimit.per_day,
    api_key: apiKey,
    api_key_prefix: apiKey.substring(0, 8),
    event_type: body.event_type,
    event_id: body.event_id,
    amount_total: data.amount_total,
    currency: data.currency || 'eur'
  }
}];

// Check update result and prepare response
const dbResult = $input.first().json;
const prevData = $('Extract Data').first().json;

if (!dbResult || !dbResult.id) {
  return [{
    json: {
      success: false,
      error: 'Failed to create/update user',
      email: prevData.email
    }
  }];
}

return [{
  json: {
    success: true,
    db_updated: true,
    user_id: dbResult.id,
    email: dbResult.email,
    api_key: dbResult.api_key,
    credits: dbResult.credits,
    plan: dbResult.subscription_plan,
    stripe_customer_id: prevData.stripe_customer_id,
    stripe_subscription_id: prevData.stripe_subscription_id,
    amount_total: prevData.amount_total,
    currency: prevData.currency,
    event_id: prevData.event_id
  }
}];

// Prepare final response with API key
const checkData = $('Check Update').first().json;

return [{
  json: {
    success: true,
    processed: true,
    email: checkData.email,
    api_key: checkData.api_key,
    plan: checkData.plan,
    credits: checkData.credits
  }
}];
